def test_case_12():
    var_0 = 3
    var_1 = True
    var_2 = 'line_length'
    var_3 = 'use_parentheses'
    var_4 = 'comment_prefix'
    var_5 = {var_2: var_1, var_2: var_0, var_2: var_1, var_3: var_1, var_2: var_2, var_4: var_2, var_2: var_1}
    var_6 = module_2.Config(**var_5)
    assert f'{type(var_6).__module__}.{type(var_6).__qualname__}' == 'isort.settings.Config'
    assert var_6.py_version == 'py3'
